import{_ as s,H as e,f as t,i}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"25-抓包分析的回顾、拾遗，和提高","description":"","frontmatter":{},"headers":[{"level":2,"title":"tcpdump 和 tshark 等命令行工具的技巧","slug":"tcpdump-和-tshark-等命令行工具的技巧","link":"#tcpdump-和-tshark-等命令行工具的技巧","children":[{"level":3,"title":"tcpdump","slug":"tcpdump","link":"#tcpdump","children":[]},{"level":3,"title":"基础参数","slug":"基础参数","link":"#基础参数","children":[]},{"level":3,"title":"tcpdump 过滤条件","slug":"tcpdump-过滤条件","link":"#tcpdump-过滤条件","children":[]},{"level":3,"title":"tshark","slug":"tshark","link":"#tshark","children":[]},{"level":3,"title":"capinfos","slug":"capinfos","link":"#capinfos","children":[]},{"level":3,"title":"editcap","slug":"editcap","link":"#editcap","children":[]}]},{"level":2,"title":"Wireshark 的技巧","slug":"wireshark-的技巧","link":"#wireshark-的技巧","children":[{"level":3,"title":"Wireshark 的解读技巧","slug":"wireshark-的解读技巧","link":"#wireshark-的解读技巧","children":[]},{"level":3,"title":"对 TCP 提示的解读","slug":"对-tcp-提示的解读","link":"#对-tcp-提示的解读","children":[]},{"level":3,"title":"TCP Window 相关的信息","slug":"tcp-window-相关的信息","link":"#tcp-window-相关的信息","children":[]},{"level":3,"title":"TCP 传输状况信息","slug":"tcp-传输状况信息","link":"#tcp-传输状况信息","children":[]},{"level":3,"title":"Wireshark 过滤器","slug":"wireshark-过滤器","link":"#wireshark-过滤器","children":[]},{"level":3,"title":"tcp.analysis 类过滤器","slug":"tcp-analysis-类过滤器","link":"#tcp-analysis-类过滤器","children":[]}]},{"level":2,"title":"排查技巧","slug":"排查技巧","link":"#排查技巧","children":[]},{"level":2,"title":"逐段测试法","slug":"逐段测试法","link":"#逐段测试法","children":[{"level":3,"title":"抓包分析思路","slug":"抓包分析思路","link":"#抓包分析思路","children":[]},{"level":3,"title":"整数值","slug":"整数值","link":"#整数值","children":[]},{"level":3,"title":"偶发性问题","slug":"偶发性问题","link":"#偶发性问题","children":[]},{"level":3,"title":"对比分析","slug":"对比分析","link":"#对比分析","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"网络排查案例课/25-抓包分析的回顾、拾遗，和提高.md","filePath":"网络排查案例课/25-抓包分析的回顾、拾遗，和提高.md","lastUpdated":1795563497000}'),n={name:"网络排查案例课/25-抓包分析的回顾、拾遗，和提高.md"};function p(l,a,E,c,o,r){return e(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="_25-抓包分析的回顾、拾遗-和提高" tabindex="-1">25-抓包分析的回顾、拾遗，和提高 <a class="header-anchor" href="#_25-抓包分析的回顾、拾遗-和提高" aria-label="Permalink to &quot;25-抓包分析的回顾、拾遗，和提高&quot;">​</a></h1><p>你好，我是胜辉。</p><p>在完成了三个实战模块之后，我们已经把三层以上，也就是网络层、传输层、应用层等的排查技术都比较完整地学习了一遍。在二十多节课里，我们学习了对 TCP 的各种行为，比如握手、挥手、拥塞、重传等行为进行排查的技巧，也对 tcpdump 和 Wireshark 进行了深度使用。</p><p>除了这些技巧以外，我们更是在 TLS 加解密和应用层 HTTP 协议等理论知识方面，做了不少深入的研究。我想，很多工具的使用技巧、案例的排查思路已经在我们的脑海中回荡，那么如果我们来一次系统性的总结和提高，对我们的学习效果一定是一种更大的促进。</p><p>所以在这节课里，我们就来对过去的二十多讲进行一次回顾、总结和提高吧。</p><h2 id="tcpdump-和-tshark-等命令行工具的技巧" tabindex="-1">tcpdump 和 tshark 等命令行工具的技巧 <a class="header-anchor" href="#tcpdump-和-tshark-等命令行工具的技巧" aria-label="Permalink to &quot;tcpdump 和 tshark 等命令行工具的技巧&quot;">​</a></h2><p>tcpdump 是我们用得最多的抓包工具，其中的基本技巧可以汇总为以下几个方面。</p><h3 id="tcpdump" tabindex="-1">tcpdump <a class="header-anchor" href="#tcpdump" aria-label="Permalink to &quot;tcpdump&quot;">​</a></h3><p>我们做抓包，一般都需要指定过滤条件，这样才能保证对系统的 CPU、内存、硬盘等资源不产生过大的影响。这里说的过滤条件又分基础参数和真正的过滤条件，我们分别来看一下。</p><h3 id="基础参数" tabindex="-1">基础参数 <a class="header-anchor" href="#基础参数" aria-label="Permalink to &quot;基础参数&quot;">​</a></h3><p>这类基础参数可能不算是用来过滤报文本身的参数，它们一般用于指定抓包的网口、报文长度等等。我们来逐个看一下。</p><p>要限定网络接口，可以用 -i 参数。比如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcpdump -i eth0</span></span>
<span class="line"><span>补充：这里还有个小的注意点。当我们用 -i any 的时候，抓到的报文就不是标准以太网</span></span></code></pre></div><ul><li>帧头格式了，这一点你需要知道一下。</li></ul><p>如果我们要查看抓包过程中的详细信息，下面这三种参数任你选择：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcpdump -v         #提供TTL等信息</span></span>
<span class="line"><span>tcpdump -vv        #提供更多信息</span></span>
<span class="line"><span>tcpdump -vvv       #提供最详细的信息</span></span>
<span class="line"><span>补充：如果你还是用 -w file.pcap 存入了文件，加上 -v 参数可以每 10 秒打印一次抓</span></span></code></pre></div><ul><li>取的报文数量。</li></ul><p>默认情况下，tcpdump 会对 IP 进行反向域名查询等操作，这些 DNS 查询等行为可能影响抓</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>包的效率。这时候就可以加上 -n 参数：</span></span>
<span class="line"><span>tcpdump -n</span></span></code></pre></div><p>为了节约抓包成本，我们经常会指定要抓取的每个报文的长度。比如，假如 TCP 没有启用扩展头部，那么指定 54 字节即可抓取到从二层帧头部到 TCP 头部的这些信息了。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcpdump -s 54</span></span></code></pre></div><h3 id="tcpdump-过滤条件" tabindex="-1">tcpdump 过滤条件 <a class="header-anchor" href="#tcpdump-过滤条件" aria-label="Permalink to &quot;tcpdump 过滤条件&quot;">​</a></h3><p>抓包的过滤条件当然是重中之重的技巧了，这里我们再复习一下。</p><p>要限定 IP，可以用下面的过滤器：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcpdump host 10.10.10.10</span></span>
<span class="line"><span>tcpdump dst host 10.10.10.10</span></span>
<span class="line"><span>tcpdump src host 10.10.10.11</span></span></code></pre></div><p>要限定端口，可以用这个：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcpdump port 22</span></span></code></pre></div><p>我们有时候也需要从已有的抓包文件中过滤出报文，然后存入一个新的文件。比如下面的例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcpdump -r file.pcap &#39;tcp[tcpflags] &amp; (tcp-rst) != 0&#39; -w rst.pcap</span></span></code></pre></div><h3 id="tshark" tabindex="-1">tshark <a class="header-anchor" href="#tshark" aria-label="Permalink to &quot;tshark&quot;">​</a></h3><p>tshark 是一个跟随 Wireshark 一起安装进系统的工具，类似情况的工具还有 editcap、mergecap、capinfos 等等，算是 Wireshark 大礼包了。这些工具都有很强大的功能，这个大礼包真是物超所值。</p><p>我们先看 tshark。在课程中，我们主要用 tshark 实现了三个不同的需求场景。</p><p>第一个场景是统计文件中的 HTTP 状态码。我们可以到Gitee里找到相关的抓包示例文件，然后运行下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tshark -r lesson17-in-shorten.pcap -T fields -e http.response.code | grep -v ^$ |</span></span></code></pre></div><p>输出如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2931 200</span></span>
<span class="line"><span>704 502</span></span>
<span class="line"><span>227 304</span></span>
<span class="line"><span>141 400</span></span>
<span class="line"><span> 45 301</span></span>
<span class="line"><span> 41 302</span></span>
<span class="line"><span> 16 408</span></span>
<span class="line"><span> 14 403</span></span>
<span class="line"><span>  6 503</span></span>
<span class="line"><span>  6 404</span></span>
<span class="line"><span>  2 206</span></span></code></pre></div><p>可见，HTTP 状态码都非常整体地统计展现出来了。所以我们做抓包分析，不仅要熟练掌握Wireshark，同时也应该多了解这些命令行工具，它们经常可以提供 Wireshark 以外的一种良好的补充。</p><p>第二个场景是解析文件中的 HTTP 事务的耗时。比如我们可以用下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tshark -r 文件名 -T fields -e http.time | grep -v ^$</span></span></code></pre></div><p>第三个场景，是在找到 HTTP 耗时最高的事务，然后找这个事务所在的整个 TCP 流的所有报文，我们可以用下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tshark -r 文件名 -T fields -e frame.number -e http.time -e tcp.stream | sort -k2 -</span></span>
<span class="line"><span>这个命令比较长，用到了多次管道符，特别是最后一个管道符后面，使用了 tshark -Y</span></span>
<span class="line"><span>&quot;tcp.stream eq xx&quot;，而这个过滤器就是把某个特定的 TCP 流给完整地展示出来，这样</span></span></code></pre></div><p>的话我们不仅可以找到 HTTP 耗时最高的事务，而且这个事务的完整的 TCP 流里的报文都展示了出来，方便我们做进一步的分析。</p><p>tshark 的功能有很多，比如它还可以查看 TCP 初始往返时间：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tshark -r file.cap -T fields -e tcp.analysis.initial_rtt | grep -v ^$</span></span></code></pre></div><p>也可以统计 TCP 重传包的数量：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tshark -n -q -r file.pcap -z &quot;io,stat,0,tcp.analysis.retransmission&quot;</span></span></code></pre></div><p>最后，tshark 其实也经常用来直接抓包，这时候它跟 tcpdump 是差不多的。比如下面这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tshark -i &quot;Wireless Network Connection&quot; -w file.pcap host 123.45.66.77</span></span></code></pre></div><h3 id="capinfos" tabindex="-1">capinfos <a class="header-anchor" href="#capinfos" aria-label="Permalink to &quot;capinfos&quot;">​</a></h3><p>这个工具主要是用来获取抓包文件的整体信息，比如我们使用下面这个命令，就获取到了抓包文件的报文数、文件大小、抓包时长等丰富的信息。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ capinfos lesson17-in-shorten.pcap</span></span>
<span class="line"><span>File name:           lesson17-in-shorten.pcap</span></span>
<span class="line"><span>File type:           Wireshark/tcpdump/... - pcap</span></span>
<span class="line"><span>File encapsulation:  Ethernet</span></span>
<span class="line"><span>File timestamp precision:  microseconds (6)</span></span>
<span class="line"><span>Packet size limit:   file hdr: 65535 bytes</span></span>
<span class="line"><span>Packet size limit:   inferred: 150 bytes</span></span>
<span class="line"><span>Number of packets:   88 k</span></span>
<span class="line"><span>File size:           9769 kB</span></span>
<span class="line"><span>Data size:           115 MB</span></span>
<span class="line"><span>Capture duration:    297.564908 seconds</span></span>
<span class="line"><span>......</span></span></code></pre></div><p>它的功能跟 Wireshark 里 Statistics 下拉菜单里的 Capture File Properties 是类似的：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/1.png" alt=""></a></p><h3 id="editcap" tabindex="-1">editcap <a class="header-anchor" href="#editcap" aria-label="Permalink to &quot;editcap&quot;">​</a></h3><p>有时候我们需要传递抓包文件，同时又不想透露应用层数据等敏感信息，那么一个简便的做</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>法，就是直接修改抓包文件中每个报文的长度。前面说过，tcpdump -s 是可以指定抓包大</span></span></code></pre></div><p>小的，而即使文件已经生成了，我们还是可以通过 editcap 名把它改小。是不是挺方便的？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>比如要把原始文件 old.pcap 的每个报文截短为 54 字节，可以执行下面的命令：</span></span>
<span class="line"><span>editcap -s 54 old.pcap new.pcap</span></span></code></pre></div><p>另外，editcap 也可以用来把 TLS key 文件跟抓包文件合并在一起，这样你在分享文件的时候，就不需要传送两个文件了，而是一个合并过的文件就可以。比如下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>editcap --inject-secrets tls,key.log in.pcap out.pcap</span></span>
<span class="line"><span>注意：命令中的 tls 跟后面的 key.log 文件名之间有一个逗号，虽然略有点奇怪，但这</span></span></code></pre></div><ul><li>就是它的格式。</li></ul><h2 id="wireshark-的技巧" tabindex="-1">Wireshark 的技巧 <a class="header-anchor" href="#wireshark-的技巧" aria-label="Permalink to &quot;Wireshark 的技巧&quot;">​</a></h2><p>Wireshark 可以算是我们课程中最闪亮的明珠了。不过很多同学在学习这门课之前，可能对Wireshark 的了解很少，一打开文件就晕了，心里只有一个念头“不明觉厉”。当然，通过课程的学习，相信你对这方面已经积累了相当不错的经验。如果你现在看到 Wireshark 窗口甚至有“亲切”的感觉，那就对了，说明你有了长足的进步，已经真正跟 Wireshark 成为密友了。</p><p>这里我们再来简单回顾一下相关的技巧。</p><h3 id="wireshark-的解读技巧" tabindex="-1">Wireshark 的解读技巧 <a class="header-anchor" href="#wireshark-的解读技巧" aria-label="Permalink to &quot;Wireshark 的解读技巧&quot;">​</a></h3><p>在解读抓包文件时，第一步一般可以查看 Expert Information。这个信息的解读方法是这样的：</p><ul><li><p>Warning 条目的底色是黄色，意味着可能有问题，应重点关注。</p></li><li><p>Note 条目的底色是浅蓝色，是在允许范围内的小问题，也要关注。</p></li><li><p>Chat 条目的底色是正常蓝色，属于 TCP/UDP 的正常行为，比如这次通信里 TCP 握手和挥手分别有多少次等，可以作为参考。</p></li><li><p>一般来说，乱序可以重点关注。</p></li></ul><p>在解读完 Expert Information 之后，我们会找到可疑的报文，展开进一步的分析。此时我们用得最多的技巧，可能就是 Follow TCP Stream 了。我们可以选中一个报文后右单击，然后选择 Follow，在二级菜单中选择 TCP Stream，这样就来到了这个报文所在的 TCP 流。基本上每次做抓包分析都会用到这一步的操作。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/2.png" alt=""></a></p><p>另外，Wireshark 默认展示的列经常不能满足我们的需求，所以我们也要学会添加自定义列的方法。简单来说，就是选择一个报文后，进入它的详情部分（界面下方），然后选中某一个属性，右单击，选择 Apply as Column 即可。比如下面这样：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/3.png" alt=""></a></p><p>上图中，我们通过添加 TTL 自定义列，就可以让每个报文的 TTL 值都在主视图中展现，极大地方便了对这些 TTL 的比较。所以我们除了掌握协议知识以外，也要挖掘各类工具的使用技巧。所谓“工欲善其事，必先利其器”也。</p><p>另外，在排查中，时间这个信息也是十分重要的。根据场景的不同，我们需要不同的 Time 列的表示方式。比如：</p><ul><li><p>当我们关注前后报文间的间隔时间时，我们会选择 Delta time 或者 Delta time displayed。</p></li><li><p>当我们关注跨度比较大的报文间隔时，最好选择 Absolute time 或者另外两个 Absolutedate 的形式。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/4.png" alt=""></a></p><h3 id="对-tcp-提示的解读" tabindex="-1">对 TCP 提示的解读 <a class="header-anchor" href="#对-tcp-提示的解读" aria-label="Permalink to &quot;对 TCP 提示的解读&quot;">​</a></h3><p>Wireshark 很方便也很强大，但如果我们脱离了对网络协议的理解，那其实还是无从下手。比如我们做得最多的 TCP 排查，就需要结合自己对 TCP 的掌握才能做好解读。</p><p>举个例子。同样是 Wireshark 关于 TCP 窗口方面的提示，TCP Window Full 跟 TCP ZeroWindow 都是什么含义，有什么差别呢？像这样的例子很多，如果你真正地从 Wireshark 给你的众多信息中获取了有效的线索，那你的排查能力必定有一个明显的提升了。</p><h3 id="tcp-window-相关的信息" tabindex="-1">TCP Window 相关的信息 <a class="header-anchor" href="#tcp-window-相关的信息" aria-label="Permalink to &quot;TCP Window 相关的信息&quot;">​</a></h3><p>就 TCP Window Full 而言，它的意思是一端的在途字节数等于另一端的接收窗口。Wireshark会根据发送出去的数据量和已经确认的数量，计算出在途字节数，然后跟另一端的接收窗口进行比较。如果两者相等，说明另一端的接收窗口已经被用满了。这个对于排查 TCP 传输速度相关的问题是很有帮助的。</p><p>然后是 TCP Zero Window，这个比较简单，就是接收窗口为零。这是主动通告对端“自己的接收窗口已经为零，不要再发送数据了”。所以你能看出来它跟 TCP Window Full 的区别了吗？</p><p>它们的区别是：TCP Zero Window 是一个体现在 TCP 报文里的信息，算是主动“投降”。而TCP Window Full 不是在报文中的信息，它是 Wireshark 自己分析出来的结论。知道了两者的区别，相信你也知道在相应的场景下，该如何结合这种解读来帮助排查了。</p><h3 id="tcp-传输状况信息" tabindex="-1">TCP 传输状况信息 <a class="header-anchor" href="#tcp-传输状况信息" aria-label="Permalink to &quot;TCP 传输状况信息&quot;">​</a></h3><p>关于 TCP 传输速度也是一个热门话题，我们在第 9~11 讲都做了比较深入的探讨。在Wireshark 里，我们可以利用下面几个图表来帮助排查。</p><ul><li><p>I/O Graph：这个可以看到 IP 报文级别的传输速度。</p></li><li><p>TCP Stream Graphs：这里又分了几种子图表，分别是：</p></li><li><p>Time Sequence (Stevens)：查看 TCP 序列号随着时间的变化趋势。</p></li><li><p>Throughput：查看传输数据量的变化趋势。</p></li><li><p>Round Trip Time：查看传输中 RTT 的变化。</p></li><li><p>Window Scaling：查看接收窗口在传输中的变化，还可以直观地找到 TCP Window Full事件。</p></li></ul><p>你可以在 Statistics 下拉菜单中找到上面的这些工具。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/5.png" alt=""></a></p><h3 id="wireshark-过滤器" tabindex="-1">Wireshark 过滤器 <a class="header-anchor" href="#wireshark-过滤器" aria-label="Permalink to &quot;Wireshark 过滤器&quot;">​</a></h3><p>过滤器这一块也是很丰富且很有价值的内容。有时候，能否写出一个高效准确的过滤器，几乎可以当做是区分我们抓包分析水准的量尺，所以对过滤器再重视也不为过。下面我们来回顾几个典型的过滤器。</p><p>在匹配字符串的时候，我们可以有以下这样的好几种选择，分别在不同的分层上实现了文本过滤。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcp contains &quot;abc&quot;</span></span>
<span class="line"><span>ip contains &quot;abc&quot;</span></span>
<span class="line"><span>http contains &quot;abc&quot;</span></span></code></pre></div><p>那如果要匹配二进制数据该如何做到呢？我们知道，每个字节是 8 位，Wireshark 用两个十六进制数字表示一个字节，我们在每个字节之间加上破折号就可以了。比如下面这样也可以搜到带“abc”的报文：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcp.payload contains 61-62-63</span></span></code></pre></div><p>当我们要根据 TCP 报文的标志位进行过滤的时候，就可以用下面这种过滤器：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcp.flags.reset eq 1      #找到RST报文</span></span>
<span class="line"><span>tcp.flags.syn eq 1        #找到握手的SYN报文</span></span>
<span class="line"><span>tcp.flags.fin eq 1        #找到挥手的FIN报文</span></span></code></pre></div><p>我们还可以根据时间匹配来过滤报文，比如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>frame.time &gt;=&quot;Mar 28, 2022 00:00:00&quot;</span></span></code></pre></div><h3 id="tcp-analysis-类过滤器" tabindex="-1">tcp.analysis 类过滤器 <a class="header-anchor" href="#tcp-analysis-类过滤器" aria-label="Permalink to &quot;tcp.analysis 类过滤器&quot;">​</a></h3><p>此外，Wireshark 的过滤器中还有一个非常重要的部分，是 TCP 分析器 tcp.analysis，当你在Wiresahrk 过滤器栏输入 tcp.analysis 后，就自动有很多的过滤器提示出来。这些过滤器经常能起到很大的帮助，因为它们大多不是直接的报文内容，而是从报文中推导出来的信息，已经包含了一定的分析价值。</p><p>比如下面这个过滤器，可以找到超过 200ms 才发回的确认报文：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcp.analysis.ack_rtt &gt;0.2 and tcp.len == 0</span></span></code></pre></div><p>当我们要找到所有的 TCP Window Full 的报文的时候，就可以输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcp.analysis.window_full</span></span></code></pre></div><p>更多的 tcp.analysis 过滤器你可以自己去 Wireshark 里摸索一下，相信你会有很大的收获。</p><h2 id="排查技巧" tabindex="-1">排查技巧 <a class="header-anchor" href="#排查技巧" aria-label="Permalink to &quot;排查技巧&quot;">​</a></h2><p>其实，网络排查很多人都在做，也都会抓包，那为什么不是每个人都可以从抓包文件中分析出有效的信息来呢？可能关键就在于我课程里提到过的两大鸿沟。</p><ul><li><p>应用现象跟网络现象之间的鸿沟：你可能看得懂应用层的日志，但是不知道网络上具体发生了什么。</p></li><li><p>工具提示跟协议理解之间的鸿沟：你看得懂 Wireshark、tcpdump 这类工具的输出信息的含义，但就是无法真正地把它们跟你对协议的理解对应起来。</p></li></ul><p>为了突破第一个鸿沟，我们需要熟悉抓包技术，知道什么时候抓包、抓哪些包，然后也有能力把抓包文件中的信息，跟应用层日志中的信息对应起来。</p><p>为了突破第二个鸿沟，我们需要深刻理解网络协议，知道 TCP、IP、HTTP 这些协议的行为和脾性，然后结合 Wireshark 的各种技巧，把网络协议跟实际现象结合起来，从而推进排查工作。</p><p>当然，填平这两个鸿沟只是我们的目标，而手段就是这里要讨论的排查技巧了。这里的内容也比较多，我选了几个典型场景和思路，希望对你有所启发。</p><h2 id="逐段测试法" tabindex="-1">逐段测试法 <a class="header-anchor" href="#逐段测试法" aria-label="Permalink to &quot;逐段测试法&quot;">​</a></h2><p>我们经常会遇到一个请求从开始到结束会经过很多环节的情况，比如：</p><ul><li>客户端 -&gt; 第四层 LB -&gt; 第七层 LB -&gt; 服务端</li></ul><p>在这种时候，我们可以做逐段测试，比如从客户端直接访问服务端，这样可以很快地确定中间这两个环节是否跟问题有直接关系了。比如像下面这样：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/6.png" alt=""></a></p><h3 id="抓包分析思路" tabindex="-1">抓包分析思路 <a class="header-anchor" href="#抓包分析思路" aria-label="Permalink to &quot;抓包分析思路&quot;">​</a></h3><p>在进入抓包分析阶段后，从经验性的排查思路这个角度来说，一般的抓包分析可以用我们在第 5 讲“定位防火墙（一）”中提到过的步骤，也就是：</p><ul><li><p>查看 Expert Information；</p></li><li><p>重点关注可疑报文（比如 Warining 级别），追踪其整个 TCP 流；</p></li><li><p>深入分析这个可疑 TCP 流的第二到四层的报文，再结合应用层表象，综合分析其根因；</p></li><li><p>结合两侧的抓包文件，找到属于同一个 TCP 流的数据包，对比分析，得出结论。</p></li></ul><p>下图就概括了这个过程，你可以来参考一下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/7.png" alt=""></a></p><h3 id="整数值" tabindex="-1">整数值 <a class="header-anchor" href="#整数值" aria-label="Permalink to &quot;整数值&quot;">​</a></h3><p>在有整数值出现的时候，我们需要提起精神，务必重点调查这个整数值背后的原因。因为一般来说，这往往意味着有人为的设置在里面，比如某种客户端超时设置。这些设置经常会跟问题有直接或间接的关系。</p><p>比如在第 15 讲，我们就发现客户端有 5 秒超时的机制，并在 Wireshark 里体现了这一点。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/8.png" alt=""></a></p><h3 id="偶发性问题" tabindex="-1">偶发性问题 <a class="header-anchor" href="#偶发性问题" aria-label="Permalink to &quot;偶发性问题&quot;">​</a></h3><p>对于偶发性问题，我们可以采用这样的策略：</p><ul><li>预估 -&gt; 开始抓包和观察 -&gt; 问题重现 -&gt; 停止抓包 -&gt; 分析</li></ul><p>下图概括了这个过程，供你参考：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/9.png" alt=""></a></p><h3 id="对比分析" tabindex="-1">对比分析 <a class="header-anchor" href="#对比分析" aria-label="Permalink to &quot;对比分析&quot;">​</a></h3><p>还有一个很关键的技术是“对比分析”。我们做抓包分析，经常要在多处抓包后做对比分析。比如以下两种典型场景：</p><ul><li><p>同一个 TCP 流在客户端和服务端的抓包文件；</p></li><li><p>LB 前后不同 TCP 连接的抓包文件。</p></li></ul><p>对于第一种场景，我们可以用报文本身的字段作为匹配条件，因为属于同一个 TCP 流，它们的这些属性字段值一定不会变化。比如用裸序列号（原始序列号），像下面的过滤器：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcp.seq_raw eq 123456</span></span></code></pre></div><p>找到同一个 TCP 流之后，就可以把两个 Wireshark 窗口都打开，放在一起进行比较。你可以回顾下第 5 讲的案例，参考我们是如何做对比分析的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/10.png" alt=""></a></p><p>而对于第二种场景，TCP 连接就是完全不同的了，所以无法像上面第一种场景那样，把 TCP报文里的字段值作为关联映射的条件。我们一般可以寻找应用层的特征，比如某个 uuid，然后运用 Wireshark 过滤器，在两侧不同 TCP 连接的抓包文件中，找到同样包含这个 uuid 的报文。比如这些过滤器：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http contains &quot;uuidxxxxx&quot;</span></span>
<span class="line"><span>tcp contains &quot;uuidxxxxx&quot;</span></span>
<span class="line"><span>ip contains &quot;uuidxxxxx&quot;</span></span>
<span class="line"><span>frame contains &quot;uuidxxxxx&quot;</span></span></code></pre></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这节课，我们是对整个课程中，不少抓包分析的技术细节进行了回顾。我在春节特别放送（三）里其实提到过，思维导图是一个很好的学习工具，所以我就汇总整理了专栏中的核心内容。因为内容也比较多，我分为了 4 个部分来分别展示，你可以通过它们快速找到你需要的知识点。</p><ul><li>排查技术</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/11.png" alt=""></a></p><ul><li>协议</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/12.png" alt=""></a></p><ul><li>系统相关</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/13.png" alt=""></a></p><ul><li>抓包分析</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25-%25E6%258A%2593%25E5%258C%2585%25E5%2588%2586%25E6%259E%2590%25E7%259A%2584%25E5%259B%259E%25E9%25A1%25BE%25E3%2580%2581%25E6%258B%25BE%25E9%2581%2597%25EF%25BC%258C%25E5%2592%258C%25E6%258F%2590%25E9%25AB%2598/14.png" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>给你留两道思考题：</p><ul><li><p>假设通信的一端发送了 TCP Zero Window 报文，并且后续没有更多新的报文过来，那么另一端是不是一直不能发送新的数据了呢？</p></li><li><p>请写一个 tshark 命令，用来过滤出抓包文件中的 DupAck。</p></li></ul><p>欢迎你把答案分享到留言区，我们一同进步、成长。</p>`,152)])])}const u=s(n,[["render",p]]);export{d as __pageData,u as default};
